package main

import (
	"bytes"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/transparency-dev/tessera/api"
	"github.com/transparency-dev/tessera/api/layout"
)

// The tiles fixture is generated by testdata/tiles/generate and verified by
// the registry's TypeScript tests from the same file (one oracle, two
// implementations); see testdata/tiles/README.md.
type tilesFixture struct {
	TreeSize      uint64            `json:"tree_size"`
	RootHashHex   string            `json:"root_hash_hex"`
	Payloads      []string          `json:"payloads"`
	LeafHashesHex []string          `json:"leaf_hashes_hex"`
	Tiles         map[string]string `json:"tiles"`
	Entries       map[string]string `json:"entries"`
}

func loadTilesFixture(t *testing.T) tilesFixture {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", "tiles", "spec-tiles-v1.json"))
	if err != nil {
		t.Fatalf("read tiles fixture: %v", err)
	}
	var fixture tilesFixture
	if err := json.Unmarshal(raw, &fixture); err != nil {
		t.Fatalf("parse tiles fixture: %v", err)
	}
	return fixture
}

func rfc6962Leaf(data []byte) []byte {
	h := sha256.New()
	h.Write([]byte{0x00})
	h.Write(data)
	return h.Sum(nil)
}

func rfc6962Node(left, right []byte) []byte {
	h := sha256.New()
	h.Write([]byte{0x01})
	h.Write(left)
	h.Write(right)
	return h.Sum(nil)
}

func testSubtreeRoot(leafHashes [][]byte, start, end int) []byte {
	if end-start == 1 {
		return leafHashes[start]
	}
	k := 1
	for k < end-start {
		k <<= 1
	}
	k >>= 1
	return rfc6962Node(testSubtreeRoot(leafHashes, start, start+k), testSubtreeRoot(leafHashes, start+k, end))
}

func TestTilesFixtureVerifies(t *testing.T) {
	fixture := loadTilesFixture(t)
	if uint64(len(fixture.LeafHashesHex)) != fixture.TreeSize || uint64(len(fixture.Payloads)) != fixture.TreeSize {
		t.Fatalf("fixture sizes disagree: %d leaves, %d payloads, size %d", len(fixture.LeafHashesHex), len(fixture.Payloads), fixture.TreeSize)
	}

	leafHashes := make([][]byte, fixture.TreeSize)
	for i, payload := range fixture.Payloads {
		want := rfc6962Leaf([]byte(payload))
		if got := fmt.Sprintf("%x", want); got != fixture.LeafHashesHex[i] {
			t.Fatalf("leaf hash %d mismatch: fixture %s, recomputed %s", i, fixture.LeafHashesHex[i], got)
		}
		decoded, err := hex.DecodeString(fixture.LeafHashesHex[i])
		if err != nil {
			t.Fatalf("leaf hash %d hex: %v", i, err)
		}
		leafHashes[i] = decoded
	}
	if got := fmt.Sprintf("%x", testSubtreeRoot(leafHashes, 0, int(fixture.TreeSize))); got != fixture.RootHashHex {
		t.Fatalf("root mismatch: fixture %s, recomputed %s", fixture.RootHashHex, got)
	}

	for path, b64 := range fixture.Tiles {
		segments := strings.Split(strings.TrimPrefix(path, "tile/"), "/")
		level, index, width, err := layout.ParseTileLevelIndexPartial(segments[0], strings.Join(segments[1:], "/"))
		if err != nil {
			t.Fatalf("tile path %q does not parse with the real layout package: %v", path, err)
		}
		if got := layout.PartialTileSize(level, index, fixture.TreeSize); got != width {
			t.Fatalf("tile %q partial size %d, layout says %d", path, width, got)
		}
		nodeCount := int(width)
		if nodeCount == 0 {
			nodeCount = layout.TileWidth
		}
		raw, err := base64.StdEncoding.DecodeString(b64)
		if err != nil {
			t.Fatalf("tile %q base64: %v", path, err)
		}
		if len(raw) != nodeCount*sha256.Size {
			t.Fatalf("tile %q has %d bytes, want %d", path, len(raw), nodeCount*sha256.Size)
		}
		var tile api.HashTile
		if err := tile.UnmarshalText(raw); err != nil {
			t.Fatalf("tile %q does not parse with the real api.HashTile: %v", path, err)
		}
		span := 1 << (level * layout.TileHeight)
		for offset, node := range tile.Nodes {
			start := int(index)*layout.TileWidth*span + offset*span
			want := testSubtreeRoot(leafHashes, start, start+span)
			if !bytes.Equal(node, want) {
				t.Fatalf("tile %q node %d hash mismatch", path, offset)
			}
		}
		if layout.TilePath(level, index, width) != path {
			t.Fatalf("tile path %q does not round-trip through layout.TilePath", path)
		}
	}

	for path, b64 := range fixture.Entries {
		index, width, err := layout.ParseTileIndexPartial(strings.TrimPrefix(path, "tile/entries/"))
		if err != nil {
			t.Fatalf("entry path %q does not parse with the real layout package: %v", path, err)
		}
		raw, err := base64.StdEncoding.DecodeString(b64)
		if err != nil {
			t.Fatalf("entry bundle %q base64: %v", path, err)
		}
		var bundle api.EntryBundle
		if err := bundle.UnmarshalText(raw); err != nil {
			t.Fatalf("entry bundle %q does not parse with the real api.EntryBundle: %v", path, err)
		}
		entryCount := int(width)
		if entryCount == 0 {
			entryCount = layout.EntryBundleWidth
		}
		if len(bundle.Entries) != entryCount {
			t.Fatalf("entry bundle %q has %d entries, want %d", path, len(bundle.Entries), entryCount)
		}
		for offset, entry := range bundle.Entries {
			if string(entry) != fixture.Payloads[int(index)*layout.EntryBundleWidth+offset] {
				t.Fatalf("entry bundle %q entry %d does not match the payload list", path, offset)
			}
		}
		if layout.EntriesPath(index, width) != path {
			t.Fatalf("entry path %q does not round-trip through layout.EntriesPath", path)
		}
	}
}
